/* ============================================================
   PATCH 1.0.5 — Безопасная правка карточек задач
   ============================================================ */

/* 1. Убеждаемся, что шапка — это flex-строка */
.tasks-grid .task-card-head {
    display: flex !important;
    flex-wrap: wrap !important; /* разрешаем перенос, если не влезет */
    align-items: flex-start !important;
    gap: 8px !important;
}

/* 2. Иконка не должна сплющиваться */
.tasks-grid .task-card-icon-wrap {
    flex: 0 0 auto !important;
}

/* 3. Блок с названием занимает всё свободное место */
.tasks-grid .task-card-titles {
    flex: 1 1 0% !important; /* 0% заставляет flex-элемент сжиматься до контента */
    min-width: 0 !important;
}

/* 4. Блок с бейджами (topright), если он остался в шапке */
.tasks-grid .task-card-topright {
    flex: 0 0 auto !important;
    display: flex !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    gap: 6px !important;
    margin-top: 4px !important;
}

/* 5. Бейджи делаем компактными и не ломающими строку */
.tasks-grid .task-card-badge {
    font-size: 0.65rem !important;
    padding: 2px 8px !important;
    white-space: nowrap !important;
}

/* 6. Блок с датами (mid) — если туда упали бейджи */
.tasks-grid .task-card-mid {
    margin-top: 6px !important;
}

/* ============================================================
   PATCH 1.0.5 — Безопасная правка карточек задач
   ============================================================ */
(function(){
'use strict';
if (window.__trkTaskCardFixV105) return;
window.__trkTaskCardFixV105 = true;

function _moveBadges() {
    var list = document.getElementById('tasksFullList');
    if (!list) return;

    list.querySelectorAll('.task-card').forEach(function(card){
        var head = card.querySelector('.task-card-head');
        var topRight = card.querySelector('.task-card-topright');
        var mid = card.querySelector('.task-card-mid');

        // Если бейджи есть и они лежат в шапке
        if (head && topRight && topRight.parentNode === head) {
            // Удаляем класс, чтобы CSS не пытался его растянуть в шапке
            topRight.classList.remove('task-card-topright');
            topRight.classList.add('task-card-badges-below');

            // Вставляем после шапки (или после блока с датами, если он есть)
            if (mid) {
                mid.parentNode.insertBefore(topRight, mid.nextSibling);
            } else {
                head.parentNode.insertBefore(topRight, head.nextSibling);
            }
        }
    });
}

// Хук на рендер списка
(function(){
    function _hook() {
        if (typeof window.__trkRenderTasksFull !== 'function') return;
        if (window.__trkRenderTasksFull._v105safe) return;
        var orig = window.__trkRenderTasksFull;
        var wrapped = function(){
            var r = orig.apply(this, arguments);
            setTimeout(_moveBadges, 40);
            return r;
        };
        wrapped._v105safe = true;
        window.__trkRenderTasksFull = wrapped;
    }
    _hook();
    setTimeout(_hook, 500);
    setTimeout(_hook, 1500);
})();

// Наблюдатель на случай прямых манипуляций
setTimeout(function(){
    var list = document.getElementById('tasksFullList');
    if (!list) return;
    new MutationObserver(function(){
        setTimeout(_moveBadges, 30);
    }).observe(list, { childList: true });
    setTimeout(_moveBadges, 200);
}, 700);

})();

/* Стиль для бейджей, перенесённых вниз */
.tasks-grid .task-card-badges-below {
    display: flex !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    gap: 6px !important;
    margin-top: 6px !important;
    width: 100% !important;
}
